\label{blomerlutsko1}
Let $n \geq 3$ and $z,w \in G$. Then for every $\epsilon >0$, as $T \to \infty$:
\begin{eqnarray*}
 E_n (T;z,w)  = O_{n, z, w,\epsilon} \left(T^{n(n-1) - \delta_n +\epsilon}\right),
\end{eqnarray*}
where the exponent $\delta_n = \delta_{n}^{BL} $ is given by $\delta_3^{BL} = 1$, $\delta_4^{BL} = 6/5$, whereas for $n\geq 5$:
\begin{equation*} 
\delta_{n}^{BL} = \frac{n}{2n-1 - \sqrt{2n^2 - 10n -4}} = 1 + \frac{1}{\sqrt{2}} + O \left( \frac{1}{n}\right).
\end{equation*}

\label{blomerlutsko2}
Let $n \geq 3$. Then for every $\epsilon >0$, as $T \to \infty$:
\begin{equation*}
 \int_{\Omega} E_n  (T;z,z)  \ d \mu(z) = O_{n, \Omega,\epsilon} \left(T^{n(n-1) - \delta_n + \epsilon}\right)
\end{equation*}
with
\begin{equation} \label{blexponent2}
\delta_n = \frac{2 (n^2-2n)}{n^2+3n-2} = 2 + O \left( \frac{1}{n}\right).
\end{equation}

The pointwise upper bound of Theorem \ref{blomerlutsko1} was a significant strengthening of previous known upper bounds. The first such upper bound was obtained by Duke--Rudnick--Sarnak \cite{Dukerudnicksarnak} with an exponent of size 
\begin{equation*}
\delta_{n}^{DRS} = \frac{1}{n+1}.
\end{equation*}
This was slightly improved by Gorodnik--Nevo--Yehoshua \cite{GNY} with a pointwise improvement of asymptotic size
\begin{equation*}
\delta_{n}^{GNY} \sim 2 \cdot \delta_n^{DRS}.
\end{equation*}

\label{ourmainthm}
Let $n \geq 3$ and fix $w \in G$. Then, there exists a full measure subset $B_w \subset G$, such that for every $z \in B_w$ and for every $\epsilon>0$ the following bound 
\begin{eqnarray*}
 E_n (T;z,w)  = O_{n,z,w,\epsilon} \left(T^{n(n-1) - \min\left\{n/2,2\right\} + \epsilon}\right)
\end{eqnarray*}
holds as $T \to \infty$, uniformly for all sufficiently large $T$. The analogous assertion holds for every fixed $z \in G$. In particular,
\begin{equation*}
E_3 (T;z,w) = O \left(T^{9/2 +\epsilon}\right), \ \ \ E_4 (T;z,w)= O \left(T^{10 +\epsilon}\right)
\end{equation*}
for almost all $z,w$.

\label{omegaresult}
For $n \geq 3$ the error term $E_n (T;z,w)$ cannot be very small for \textit{every} fixed pair $z,w$. In particular we have
\begin{equation*}
E_n (T;I_n,I_n)=  \Omega \left(T^{n(n-1)-2}\right),
\end{equation*}
where by $I_n$ we denote the identity matrix.

\label{pretrace formula}

Let $f\in C_{c}^{\infty}(G)$ be a bi-$K$-invariant function. Then
\begin{equation}\label{kernel spectral}
K_{f}(z,w)=\int_{\Omega}h_f({\mu}_\omega)\overline{u_\omega (z)}u_\omega (w)\,d\omega.
\end{equation}
The contribution of the constant eigenfunction corresponding to ${\mu}_0=\rho, \, u_0=V^{-1/2}$ is
\begin{equation*}
    \frac{1}{V}\int_{G}f(g)\,dg.
\end{equation*}
    For fixed $w$, the left hand side is a compactly supported, smooth function of $z$ on the quotient orbifold and in particular belongs in $L^2(X)$.

With our convention of the automorphic kernel, with the spectral expansion \eqref{kernel spectral} we will use either regular synthesis
    \begin{equation}\label{regular synthesis operator}
        Sc=\int_{\Omega}c(\omega)u_\omega \,d\omega,
    \end{equation}
    with
    \begin{equation*}
        c(\omega)=h_f({\mu}_\omega)\overline{u_\omega },
    \end{equation*}
    or conjugated synthesis
    \begin{equation}\label{conjugated synthesis operator}
        \overline{S}c=\int_{\Omega}c(\omega)\overline{u_\omega} \,d\omega, 
    \end{equation}
    with 
    \begin{equation*}
         c(\omega)=h_f({\mu}_\omega)u_\omega ,
    \end{equation*}
    depending on whether we fix $w$ and prove our assertion for almost all $z$ (in this case we use conjugated synthesis) or vice versa.

\label{non constant bound}
    For $n\geq 3$, every non constant component of the spherical automorphic spectrum of ${\hbox{SL}(n, {\mathbb Z})} $ satisfies
    \begin{equation*}
       {\beta}({\mu}_\omega) :=   \| \Re({\mu}_\omega)\|_{\infty} \leq \frac{n-2}{2}.
    \end{equation*}
This includes the cuspidal and residual discrete spectra and the induced continuous spectrum.

For the parametrization of the spectrum and the deep input of the classification of the residual spectrum of general linear groups we follow \cite{blomerlutsko}; see also \cite{goldfeld, mw1, mw2}. We recall the parameters explicitly for completeness.
\par
Choose a partition of $n$ into $q$ blocks 
\begin{equation*}
    n=d_1+d_2+...+d_q,
\end{equation*}
where for each $j$ we choose a divisor $f_j \mid d_j$. For $f_j\geq 2$, choose a cuspidal automorphic datum on $GL_{f_j}$, whose archimidean parameter is denoted by $\nu_j=(\nu_{j,1},...,\nu_{j,f_j})$. The classical Jacquet-Shalika bounds stated in \cite[eq.~13]{blomerlutsko}, give
\begin{equation}\label{Jacquet Shalika}
  \|\Re\nu_j\|_{\infty}\leq \frac{1}{2}.
\end{equation}
For $f_j=1$, put $\nu_j=\textbf{0}$. Finally choose $s_j\in i{\mathbb R}$ satisfying 
$\sum_{j}d_js_j=0$ and put $\ell_j=d_j/f_j$. The entries contributing by the $j$-th block to the full parameter are equal to
\begin{equation}\label{entries}
    \nu_{j,a}+s_j+\frac{\ell_j-1}{2}-c,\quad 1\leq a\leq f_j,\,\,0\leq c\leq \ell_j-1.
\end{equation} 
In total, these blocks have $\sum_{j}f_j \, \ell_j=n$ entries. The cases $q=1$ include cuspidal representations and discrete Speh representations; varying the imaginary parameters for $q>1$ gives the induced continuous components. The formula \eqref{entries}, rather than a temperedness assumption, is what controls the possible large real parts.
\par
Since $s_j$ is imaginary, the maximum absolute real part in the $j$-th block is at most 
\begin{equation}\label{real part bound}
    \frac{1}{2}\left(\frac{d_j}{f_j}-1\right)+\frac{1}{2}\textbf{1}_{f_j\geq 2}.
\end{equation}
Indeed the shifts in \eqref{entries} range between $-(\ell_j-1)/2$ and $(\ell_j-1)/2$ and then \eqref{Jacquet Shalika} provides the extra factor $1/2$ when $f_j\geq 2$. This recovers exactly \cite[eq.~13]{blomerlutsko}.
\par 
Now if $f_1=1$, expression 
\eqref{real part bound} equals $(d_j-1)/2$. The case $d_j=n$ forces $q=1$; the inducing parameter is then zero and the block consists of the entries of $\rho$. This is precisely the constant representation in the parametrization under consideration. Once we remove this, we get $d_j\leq n-1$ and then 
\begin{equation*}
    \frac{d_j-1}{2}\leq\frac{n-2}{2}.
\end{equation*}
Moving on, if $f_j\geq 2$, then expression \eqref{real part bound} simplifies to $d_j/(2f_j)$, which is at most $n/4$.
\par
For $n=3$, the divisibility condition $f_j \mid d_j$ leaves only the choices $(d_j,f_j)=(2,2)$ or $(3,3)$ when $f_j\geq 2$. In either case $d_j/(2f_j)=1/2=(n-2)/2$. Finally, for $n\geq 4$ it is straightforward 
\begin{equation*}
    \frac{n}{4}\leq \frac{n-2}{2}
\end{equation*}
and the required bound follows. Therefore, every block satisfies the desired bound and taking the maximum over all the blocks proves the assertion over $\Omega'$.

\label{local spectral density}
    Let ${\mu}\in i\mathfrak{a}^{\ast}$ , $B({\mu})\subset \mathfrak{a}_{{\mathbb C}}^{\ast}$ a ball of size $O(1)$ about ${\mu}$ and $w\in G$. Then 
\begin{equation*}
    \int_{B(\mu)}|u_\omega (w)|^2\,d\omega\ll_{w} \mathcal{W({\mu})}.
\end{equation*}

\label{blomer local weyl}
    Let $L\geq 1$ and $w\in G$ fixed. Then
\begin{equation}\label{coarse shell bound}
\int_{\Omega_L}|u_\omega(w)|^2\,d\omega\ll_{w,n}L^{m+r} .
\end{equation}

\label{remark34}
    The same reasoning justifies the use of a rapidly decaying spectral multiplier at a fixed point. If $a({\mu})\ll_{A}(1+\|{\mu}\|)^{-A}$, for every $A$ then 
    \begin{equation*}
        \int_{\Omega}|a({\mu}_\omega)|^2|u_\omega(w)|^2\,d\omega<\infty,
    \end{equation*}
    by summing \eqref{coarse shell bound} over dyadic $L$. Accordingly the synthesis against $\overline{u_{\omega}(z)}$ 
    is a well defined $L^2(X)$ function. The smooth kernels used in the proof below have such multipliers after the smoothing factor is inserted. This provides an explicit spectral justification alongside the geometric compact-support argument of Proposition \ref{pretrace formula}.

\cite[Lemma~2]{blomerlutsko} \label{mollifier decay properties}
Let $0<\delta<1$, any $A>0$ and $\psi_\delta$ as above. Also let 
\begin{equation*}
    {\hat{\psi}_{\delta}}:=h_{\psi_\delta}, 
\end{equation*}
the spherical transform for this family of mollifiers. Then 
\begin{equation*}
{\hat{\psi}_{\delta}}(\rho)=1 ,\quad  |{\hat{\psi}_{\delta}}({\mu})|\ll_{n,A}(1+\delta U)^{-A}.
\end{equation*}

\label{new transform bound}
    Let $n\geq 3$, $\eta>0$, ${\kappa}>0$ and $C\geq 1$. Let $h_T=h_{k_{T}}$ and define the operator $D=T\partial_T$. Uniformly for $T \geq 2$, for parameters ${\mu}$ in the spherical unitary spectrum and for $U\leq C T^{2-{\kappa}}$ we get 
    \begin{equation}\label{Dq estimate}
|D^{q}h_T(\mu)|\ll_{n,\eta,\kappa}T^{m+n\beta+\eta}U^{q-m/2-(1+\beta)/2}\mathcal{G}({\tau})   \end{equation}
for $q=0,1$, where $\beta = \beta(\mu)$ and 
    \begin{equation}\label{G definition}
        \mathcal{G}({\tau})=\prod_{j=1}^{n}(1+\max_i {\tau}_i-{\tau}_j)^{-1/2}+\prod_{j=1}^{n}(1+{\tau}_j-\min_i {\tau}_i)^{-1/2}.
    \end{equation}

We begin with the Mellin representation of the spherical transform 
    \begin{equation}\label{spherical}
    h_T({\mu})= \frac{\pi^{m/2}}{2^n}T^{m}\int_{(c)}T^{ns}\frac{\prod_{j=1}^{n}\Gamma\left(\frac{s-{\mu}_j}{2}\right)}{\Gamma\left(ns/2+m/2+1\right)}\,\frac{ds}{2\pi i},
\end{equation}
for $c>0$ sufficiently large. This can be proven by the definition of the spherical transform employing the Haar measures for the subgroups $A$ and $N$ (see \cite[Lemma ~3]{blomerlutsko}). For the vertical line of integration $(c)$ we write $c=s+it$ and for the coordinates of the spectral parameter ${\mu}_j=m_j+i{\tau}_j$, where without loss of generality (due to Weyl invariance) we have ordered the imaginary parts such that ${\tau}_1\geq...\geq {\tau}_n$. Consequently we get $\sum{\tau}_j=0$, $\sum m_j=0$ and ${\tau}_1\asymp-{\tau}_n\asymp\|{\tau}\|_\infty$. Stirling's formula reads 
\begin{equation*}
    |\Gamma(x+it)|\sim\sqrt{2\pi}e^{-\pi|t|/2}|t|^{x-1/2}.
\end{equation*}
We will denote with $pol$ the exponential behavior and $exp$ the exponential behavior of the Gamma quotient
\begin{equation*}
    \frac{\prod_{j=1}^{n}\Gamma\left(\frac{s-{\mu}_j}{2}\right)}{\Gamma\left(ns/2+m/2+1\right)}.
\end{equation*}
Then we get
\begin{eqnarray*}
&&pol\ll_{\sigma}\left(\frac{1}{1+|t|}\right)^{\frac{n\sigma}{2}+\frac{m}{2}+\frac{1}{2}}\prod_{j=1}^{n}(1+|t-{\tau}_j|)^{\frac{{\sigma}-m_j-1}{2}},\\
&&exp= e^{-\frac{\pi}{4}\mathcal{E}(t)},\quad \mathcal{E}(t)=\sum_{j=1}^{n}|t-{\tau}_j|-n|t|.
\end{eqnarray*}
On a vertical line $(c)$ away from the poles, the far tail of the Gamma quotient is bounded by 
\begin{equation*}
    O_{n,c}(\sigma^{-\frac{n^2+n+2}{4}}).
\end{equation*}
The same tail after multiplication by $m+ns$ is integrable for every $n\geq 3$. Dominated convergence proves continuous differentiability and allows the passage of the $D$ operator inside the integral. This also provides sufficient decay to allow us to move freely the line of integration. We get 
\begin{equation*}
    D^qh_T({\mu})=\frac{\pi^{m/2}}{2^n}T^{m}\int_{(c)}(m+ns)^{q}T^{ns}\frac{\prod_{j=1}^{n}\Gamma\left(\frac{s-{\mu}_j}{2}\right)}{\Gamma\left(ns/2+m/2+1\right)}\,\frac{ds}{2\pi i},
\end{equation*}
and using $\Gamma(z+1)=z\Gamma(z)$ this becomes
\begin{equation}\label{Dq integral}
    D^qh_T({\mu})=\frac{\pi^{m/2}}{2^{n-q}}T^{m}\int_{(c)}T^{ns}\frac{\prod_{j=1}^{n}\Gamma\left(\frac{s-{\mu}_j}{2}\right)}{\Gamma\left(ns/2+m/2+1-q\right)}\,\frac{ds}{2\pi i}.
\end{equation}
For $q=0$ the assertion is proven in \cite[Lemma ~3]{blomerlutsko}, so for completeness we need to include the case $q=1$. We can also assume that $0<{\kappa}<2$, since a larger value restricts the range further and bounded admissible values of $T$ can be absorbed in the constant. Let
\begin{equation*}
    Q_{q}(s,{\mu})=\frac{\prod_j \Gamma((s-{\mu}_j)/2)}{\Gamma(ns/2+m/2+1-q)}.
\end{equation*}
The polynomial and exponential behavior of $Q_q(s,{\mu})$ follow in a similar fashion as above, where for $q=1$ we simply get an additional factor $-q$ in the exponent of the first term of $pol$, i.e.
\begin{equation}\label{gamma quotient bounds}
    |Q_{q}(s,{\mu})|\ll_{\sigma} \left(\frac{1}{1+|t|}\right)^{\frac{n\sigma}{2}+\frac{m}{2}+\frac{1}{2}-q}\prod_{j=1}^{n}(1+|t-{\tau}_j|)^{\frac{{\sigma}-m_j-1}{2}}\cdot e^{-\frac{\pi}{4}\mathcal{E}(t)}
\end{equation}
The possible poles of $Q_{q}(s,{\mu})$ are 
\begin{equation}\label{poles}
    p_{j,k}={\mu}_j-2k,\quad 1\leq j\leq n,\quad k=0,1,... \quad .
\end{equation}
Some might be canceled by zeros of the reciprocal denominator. It is convenient to retain them in the list since counting a canceled pole causes no difficulty.
\\\\
\textbf{The contour to the far left.} Choose a large number $L$, with $L    \geq n+2$, so that the line $\Re s=-L$ has a fixed positive distance, depending only on $n$, from every $\Re p_{j,k} =m_j-2k$ of a numerator pole. Such a choice can be made in any prescribed unit interval sufficiently far to the left; for each $j$, the numbers $m_j-2k$ have spacing $2$, so only $O_n(1)$ of them are relevant to that interval. We shall increase the prescribed interval and hence $L$, when a larger saving is needed.
\par
On $s=-L+it$, with $|t|\leq 2U$ and $L$ large enough, all numerator exponents in \eqref{gamma quotient bounds} are negative (recall that $\Re{\mu}\in C_\rho$). Dropping their factors and simply bounding the exponential contribution by $O(1)$, we get for a fixed constant $B_n$,
\begin{equation*}
    |Q_q(-L+it,{\mu})|\ll_{n,L}U^{nL/2 +B_n}.
\end{equation*}
The contribution of this segment to the integral \eqref{Dq integral} is 
\begin{equation}\label{far left 1}
    O_{n,L}(T^{m-nL} U^{nL/2+B_n})=O_{n,L,C}(T^{m-n{\kappa} L/2 +2B_n}).
\end{equation}
For $|t|>2U$ every $1+|t-{\tau}_j|$ appearing in the product in \eqref{gamma quotient bounds} is $\asymp$ to $1+|t|$. Working out the exponents in \eqref{gamma quotient bounds} the contribution of the tail to the integral is
\begin{equation}\label{far left 2}
    O_{n,L}(T^{m-nL} U^{1-\frac{m}{2}-\frac{n+1}{2}+q})=O_{n,L}(T^{m-nL}U^{1-A_n+q})
\end{equation}
with $A_n=m/2+(n+1)/2> 2$, for every $ n\geq 3$.
\par
It follows that the whole integral on the far left line is $O(T^{-B})$ for any prescribed $B>0$, upon choosing $L$ sufficiently large in terms of $n,{\kappa} , B$. The constants may depend on $L$, which is now fixed. 
\\\\
\textbf{Grouping the poles.} Between the initial vertical line $(c) = \{\Re s = c\}$ and the vertical line $(-L) = \{\Re s=-L\}$ there are at most $M=M(n,L)$ poles $p_{j,k}$, counting multiplicity. This number is independent of $U$. Merely requiring the ${\mu}_j$ to be distinct would not make the poles distinct: ${\mu}_j-{\mu}_i\in 2{\mathbb Z}$ can also produce coincidences. Moreover, estimates of  separate simple residues are not uniform as such a coincidence is approached.
\par
Choose a small number $a$. Around each crossed point $p_{j,k}$, draw a disc of radius $a$ and take the boundaries of the connected components of their union (see figure \ref{fig:poles pic}). The radius is chosen smaller than the fixed separation from both vertical lines. Every boundary point has distance at least $a$ from each crossed pole and has a fixed positive distance from every uncrossed pole. The total boundary length is at most $2\pi aM$, and the diameter of each component is at most $2aM$. The boundaries may be treated as piecewise smooth contours; an arbitrary small adjustment avoids any tangencies. The residue theorem expresses the sum of residues inside a component as the integral on its boundary, with no separation assumption on the individual poles.

Select a point $p_{j,k}=m_j-2k+i{\tau}_j$ in a given component and parametrize $s=\sigma+it$ the points on its boundary. Then
\begin{equation*}
    \sigma=m_j-2k+O(Ma),\quad t={\tau}_j+O(Ma).
\end{equation*}
Set 
\begin{equation*}
    U_j=1+|{\tau}_j|,\quad d_{ij}=1+|{\tau}_j-{\tau}_i|,\quad d_j=\min({\tau}_1-{\tau}_j,{\tau}_j-{\tau}_n),
\end{equation*}
where the imaginary parts $\tau_j$ have been ordered. 
